    <text x="0" y="121">very slow 500</text><rect x="120" y="112" width="250" height="9" rx="2" fill="var(--fg-3)"/>
  </g>
  <text x="0" y="146" fill="var(--fg-3)" font-size="11" font-family="var(--font-mono)" letter-spacing="0.08em">FIRSTMATE 3000 (effects.css)</text>
  <g font-family="var(--font-mono)" font-size="11" fill="var(--fg-1)">
    <text x="0" y="165">--dur-fast 160</text><rect x="120" y="156" width="80" height="9" rx="2" fill="var(--accent)"/>
