  function picked(name) {
    var el = root.querySelector('input[name="' + name + '"]:checked');
    return el ? el.value : "";
  }
  function snapshot() {
    var s = { entranceMs: Number(picked("entrance")), driftPx: Number(picked("drift")), reducedMotion: !!root.querySelector('input[name="reduced"]:checked') };
    root.style.setProperty("--pv-dur", (s.reducedMotion ? 0 : s.entranceMs) + "ms");
